        .primary => try self.copySelectionToClipboards(
            sel,
            &.{.selection},
            .mixed,
        ),

        // Only the standard clipboard is set.
        .clipboard => try self.copySelectionToClipboards(
            sel,
            &.{.standard},
            .mixed,
        ),

